-- Queer Atlas: Bordeaux venue, event and service intelligence
-- Run after city-bordeaux-curated-v1.sql. Researched 2026-08-14.

begin;
alter table if exists public.places add column if not exists venue_intel jsonb not null default '{}'::jsonb;
alter table if exists public.events add column if not exists event_intel jsonb not null default '{}'::jsonb;
alter table if exists public.services add column if not exists service_intel jsonb not null default '{}'::jsonb;

with researched as (
 select * from jsonb_to_recordset($bordeaux_place_intel$
[
 {"name":"Philippe Bar Queer","patch":{"queue_wait":"The room is more likely to feel suddenly full than to produce a formal rope line. Early drinks and weekday formats are normally easy; drag, karaoke and weekend dance dates can compress the small bar after 22:00. Current booking listings claim substantial event capacity, but that should not be mistaken for unlimited public floor space.","best_nights":"Pick a programmed night: drag, an open stage or karaoke reveals why Philippe matters more clearly than a random quiet hour. Happy hour from 18:00 to 20:00 suits a first visit and conversation; later pop and electro shift the room toward dancing.","crowd_mix":"Queer women, gay men, trans and non-binary guests, younger locals, after-work friends and allies all appear. Reviews describe a genuinely broad LGBTQ+ room rather than a bar aimed at one male niche. Tourists join easily because Saint-Paul is central, but regulars and local performers give it its tone.","dress_code":"No appearance code is published. Everyday Bordeaux casual, bright night-out pieces, trainers and full performance looks all make sense. Bring valid ID, but do not treat the safe-space language as permission to photograph performers or guests without asking.","staff_inclusivity":"The venue explicitly presents itself as a safe, inclusive queer bar and hosts community artists. Most fresh reviews praise fast, warm service and feeling at ease; one visitor described being largely ignored during a quiet late arrival. The honest read is strong institutional intent with normal variation in individual service.","review_signal":"Current public feedback is unusually strong for a new venue: roughly 4.9 across about 140 aggregated ratings, with cocktails, price, atmosphere and staff repeated in recent 2026 comments. The thin point is longevity, not enthusiasm. Its programme and audience should be checked again as the bar matures.","source_urls":["https://www.privateaser.com/lieu/57923-philippe-bar-queer","https://wanderlog.com/place/details/15190395/philippe-bar-queer","https://festival.cinemarges.fr/grille-2026"],"research_status":"current_operation_plus_fresh_review_consensus","updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Coco Loko","patch":{"queue_wait":"There is no cover on ordinary nights, but the central room can become difficult to move through near midnight. Local advice specifically warns that some weekends are packed. Go soon after 18:00 for a seat and an actual conversation; Pride, a guest drag artist or a popular game night can turn that into a shoulder-to-shoulder bar.","best_nights":"Thursday's social game is designed for meeting people; a drag or DJ date is better for spectacle; Friday and Saturday deliver the loudest two-room party. If this is your first Bordeaux night, early Thursday gives more local contact than arriving at 01:00 when both rooms are already at full heat.","crowd_mix":"Gay men form a visible core, but queer women, mixed friend groups, drag fans, students and visitors are part of the normal picture. The seven-night schedule produces more tourists than the smaller neighbourhood bars. The crowd becomes younger and less conversational as the lower electronic room fills.","dress_code":"No formal code: shirts, denim, trainers, crop tops, drag and casual holiday clothes coexist. Dress for a cramped, warm room and stairs between levels. A playful look fits, but the bar's accessibility and bag reality matter more than fashion.","staff_inclusivity":"The venue markets directly to gay, lesbian and friendly audiences, and reviews praise individual team members and even the cleanliness of the toilets. As with any very busy bar, service becomes less personal at peak. Ask before assuming the downstairs room or toilets meet a specific mobility need.","review_signal":"Current evidence combines official tourism endorsement, an active company registration and a mixed but largely positive traveller record. Party energy, drag and hospitality receive praise; crowding and the generic feel of the busiest nights are the most useful cautions. It works best as a lively anchor, not a quiet community salon.","source_urls":["https://www.bordeaux-tourism.co.uk/bordeaux-night/bordeauxs-gay-and-lgbtq-bars","https://annuaire-entreprises.data.gouv.fr/etablissement/79936590300027","https://www.tripadvisor.fr/Restaurant_Review-g187079-d12856957-Reviews-Coco_Loko-Bordeaux_Gironde_Nouvelle_Aquitaine.html","https://www.reddit.com/r/bordeaux/comments/1ircoei"],"research_status":"official_tourism_plus_current_registry_and_review_consensus","updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Le Plumeau","patch":{"queue_wait":"A normal opening around 21:00 is straightforward; a drag-pop show can have the little room buzzing by 22:00. Reports describe the floor already well occupied before the performance on a strong Saturday. Arrive early if seeing the stage matters, because the venue's charm comes from closeness and that also limits sightlines.","best_nights":"Thursday through Sunday each needs its actual flyer. A named drag show or Pop Fever date gives the fullest house; the occasional Sunday tea dance starts earlier and feels more social. Do not rely on a generic weekend ranking when the artists are the reason to go.","crowd_mix":"Queer women, gay men, drag followers, thirty-something friend groups and allies mix more evenly here than in a men-focused bar. Current local writing presents it as open without erasing its LGBTQ+ centre. Regular performers keep the room Bordelais even when Pride visitors arrive.","dress_code":"Pop glamour, sequins, a good vintage shirt or simple jeans all work. There is no stated face-control code. The useful preparation is comfortable dancing footwear and respect for performers working at close range.","staff_inclusivity":"The bar calls itself a safe LGBTQ+ space, participates visibly in Pride and works with queer collectives. Local reports emphasise a benevolent atmosphere rather than merely rainbow decor. One similarly named venue outside Bordeaux has negative reviews, so use the exact Premeynard address and do not merge their reputations.","review_signal":"Recent Bordeaux coverage describes fast service, generous drinks and a room that pulls reluctant spectators into the dance floor. Independent review volume is still modest and several directories confuse it with an Andernos bar. The verified signal is therefore programme, local reporting and active organiser collaborations rather than a synthetic star score.","source_urls":["https://quoifaireabordeaux.com/bar-queer-le-plumeau-bordeaux/","https://www.misterbandb.com/gay-guide/france/bordeaux/parties","https://vibes.lgbt/en/blog/sorties-lgbtq-fr-bordeaux-25-05-2026"],"research_status":"current_local_editorial_plus_organiser_programme_address_disambiguated","updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Buster Bar","patch":{"queue_wait":"With two rooms holding only about forty people, capacity matters more than a long street queue. Earlier entry is easy; a theme night can make the upstairs feel full quickly. The venue is intimate enough that an empty hour and a packed hour can occur on the same night.","best_nights":"Choose by the current theme and audience code. A festive Friday or Saturday is best for a busier male crowd, while earlier in the week favours conversation with the hosts. If a dress or fetish code is announced, take it literally rather than expecting an ordinary cocktail evening.","crowd_mix":"Primarily gay and bisexual men, including local regulars, visitors and an adult cruise audience. It is narrower than Philippe, Coco Loko or Le Plumeau and should not be represented as an all-community queer room. Tourism visibility brings international guests despite the tiny scale.","dress_code":"Everyday casual works on an ordinary night; some themed cruise editions impose or strongly invite a specific code. Check the official Facebook post before leaving. Consent, phones and upstairs behaviour matter far more than looking polished.","staff_inclusivity":"Bordeaux Tourism names the hosts and describes a convivial welcome, while traveller listings repeatedly mention cocktails and friendliness. Inclusion is intentionally audience-specific: welcoming gay and bi men is not the same as serving every gender. Ask directly about mobility because two floors and a compact layout are obvious constraints.","review_signal":"The stable points across tourism, traveller and specialist guides are its address, nightly late format, friendly hosting and male cruise identity. Public review volume is not large enough for confident scoring. The useful warning is category: this is an adult gay men's bar with intimate space, not a broad dance club.","source_urls":["https://www.bordeaux-tourism.co.uk/bordeaux-night/bordeauxs-gay-and-lgbtq-bars","https://fr.travelgay.com/venue/buster","https://www.tripadvisor.fr/Attraction_Review-g187079-d13833383-Reviews-Buster-Bordeaux_Gironde_Nouvelle_Aquitaine.html"],"research_status":"official_tourism_plus_specialist_category_consensus","updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Ultra Klubs","patch":{"queue_wait":"The main arrival wave lands after midnight and can tighten around door checks on a headline drag or Pride date. Ordinary weekends are less dramatic than the club's 500-capacity image suggests. Going near opening avoids the queue but may mean waiting for the dance floor to become alive.","best_nights":"Friday and Saturday after 01:00 are the dependable large-room choice; a listed drag or themed party is better than selecting solely by weekday. Thursday can be cheaper or free when programmed, but may not deliver the full-stage version.","crowd_mix":"Gay men, queer women, trans and non-binary clubbers, straight friends, drag audiences, students and tourists form a visibly mixed floor. Reviews praise the social diversity more consistently than any single music style. The VIP area adds a conventional club layer that is less community-centred.","dress_code":"Smart casual, clubwear, trainers and expressive queer looks are all reported; no stable strict code could be verified. Bring physical ID and check the specific party. Practical shoes help because the night often runs to 07:00.","staff_inclusivity":"Several current reviews praise a kind door and a management team that answers criticism rather than ignoring it. Others report uneven bar experiences. The venue's drag and LGBTQ+ programming is concrete evidence, but a large mixed club cannot promise the intimacy of a community-run room.","review_signal":"Fresh 2026 review summaries are genuinely mixed: crowd diversity, atmosphere and friendly security earn praise; weak drinks, DJ transitions, price and cleanliness draw criticism. That split is more informative than a single rating. Choose for scale and a named programme, not flawless polish.","source_urls":["https://www.bordeaux-tourism.co.uk/bordeaux-night/bordeauxs-gay-and-lgbtq-bars","https://fr.restaurantguru.com/ULTRA-KLUBS-Bordeaux","https://maps.apple.com/place?place-id=I7413C143F003D568"],"research_status":"official_tourism_plus_fresh_2026_review_consensus","updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Crunch Sauna","patch":{"queue_wait":"Reception usually moves quickly; the question is whether the crowd has arrived. Themed naturist periods and weekend late afternoons are more social, while weekday opening can feel calm. Entry pricing and age reductions are published, so prepare rather than negotiating at the desk.","best_nights":"Friday naturist hours after 19:00 and the weekend bring the broadest movement. Wednesday youth offers target younger guests, while Monday's relaxed format suits first-time orientation. Check the current theme because it changes both dress and pace.","crowd_mix":"Adult gay and bisexual men across ages, mostly local with some regional and tourist traffic. Recent reviews specifically call the clientele diverse, but a small venue can still feel dominated by whichever group arrives together. It remains men-only, not a general LGBTQ spa.","dress_code":"Street clothes stay in the locker. Towel or naturist rules depend on the session, and fetish gear is only relevant when announced. Shower, respect phone bans, ask before contact and use the emergency exits staff point out.","staff_inclusivity":"Warm ownership and reception are the clearest recurring positives in 2026 reviews, along with cleanliness and upgraded changing areas. One account describes aggressive behaviour from another guest, a reminder that friendly staff do not remove the need for active consent enforcement. Report problems immediately rather than absorbing them.","review_signal":"A current aggregate of about 4.4 from more than 550 Google reviews is supported by fresh written praise for cleanliness, staff and facilities. Negative comments focus on occasional client conduct or an experience that felt too compact. The consensus is a cared-for local bathhouse, not a luxury mega-spa.","source_urls":["https://sauna-crunch.com/","https://www.gayout.com/fr/europe/france/bordeaux/saunas/crunch-sauna","https://everydaypride.eu/b/crunch-sauna","https://www.petitfute.com/v1524-bordeaux-33000/c9998-coquin/c1044-s-amuser-sortir/c208-sauna/2100301-sauna-crunch.html"],"research_status":"official_operation_plus_large_fresh_review_consensus","updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Traxx Bordeaux","patch":{"queue_wait":"A line is unusual; a membership or entry check is the only predictable pause. Current reviews more often complain of a room being too quiet than too full, especially on weekday afternoons. A late theme session gives better odds than simply following an open-now directory badge.","best_nights":"Wednesday naked, Thursday fetish and weekend hard-play formats appear consistently in specialist calendars, but verify the current official post. Friday and Saturday late sessions are generally the safer choice for numbers; Sunday afternoon suits a slower local crowd.","crowd_mix":"Adult gay and bisexual men, mainly local and regional, with visitors during Pride and wine-tour weekends. Age and body types vary, but the explicitly male cruise format is narrow by design. The theme can skew the crowd more than the day.","dress_code":"Ordinary arrival clothing, then underwear, naked or fetish rules according to the announced session. Bring ID and minimal valuables; phones and photography should stay away from play areas. Never interpret the room or theme as blanket consent.","staff_inclusivity":"Recent comments repeatedly call reception friendly and the multiple rooms clean. That is credible positive evidence within the venue's men-only remit. Anyone outside that audience should choose a different venue, and mobility details should be confirmed before arrival because the club spans several zones.","review_signal":"A current local aggregate sits near 4.0 from roughly seventy reviews. Equipment, cleanliness and staff receive praise; price and empty off-peak sessions are the repeated negatives. Timing is therefore the strongest practical recommendation, not a promise that every open hour has a crowd.","source_urls":["https://autour-de-moi.pro/fiche/traxx-cruising-club-bordeaux/","https://spartacus.gayguide.travel/goingout/bordeaux/81218_Traxx","https://fr.gcruising.com/lieu-drague/5311%2Cle-traxx-de-bordeaux"],"research_status":"current_local_reviews_plus_specialist_schedule_with_hours_caveat","updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Sauna Le Saint","patch":{"queue_wait":"The daytime schedule rarely creates a conventional queue. Audience composition is the variable, so contact the venue if a particular mixed format matters. Prices differ by guest category and are published on the official site.","best_nights":"There is no night: the venue closes at 19:00. The best visit is the afternoon aligned with the audience or theme you want. Treat it as a deliberate daytime adult stop rather than a pre-club version of Crunch.","crowd_mix":"Solo men, couples, women, trans guests and cross-dressers are explicitly welcomed, though the balance changes by session. That breadth is unusual in Bordeaux adult venues. It remains a sexual social space, not a conventional wellness spa.","dress_code":"Locker-room rules replace fashion. Towel, underwear or a themed look depends on the session, and no one is obliged to participate. The official phrase that everything allowed is optional should guide every interaction.","staff_inclusivity":"The published policy is unusually clear about broad adult gender welcome, respect, courtesy and choice. That is stronger than an unsourced friendly label. Independent review volume is limited, so visitors should still report boundary problems immediately and confirm physical access.","review_signal":"Operational information is well documented by the venue itself; large current review samples are not. The useful editorial signal is distinction: mixed-adult audience, daytime hours and a modest facility set. Anyone seeking a large men-only late sauna should choose Crunch instead.","source_urls":["https://sauna-le-saint.fr/"],"research_status":"official_policy_and_operation_verified_limited_independent_reviews","updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Bien Public","patch":{"queue_wait":"Ordinary restaurant and bar hours are accessible, but a 1,500-person VendrediXXL or Pride after creates its own ticket and security flow. Arrive near doors for a major queer edition, especially if the cabaret or downstairs floor matters. Sunday lunch has none of that club pressure.","best_nights":"Choose the programme, not Friday by default. VendrediXXL, La Bordelle or Pride-linked dates transform the full building; a normal Wednesday works for drinks and culture but is not necessarily queer-led. Sunday is useful for a calmer meal and right-bank walk.","crowd_mix":"On queer takeovers: LGBTQ+ locals across genders, cabaret audiences, dancers, kink communities and visitors. On ordinary days: a broad Bordeaux culture and food crowd. The venue is a platform whose audience changes with the organiser.","dress_code":"No standing restaurant code. Queer editions invite everything from casual riverfront layers to clubwear and fetish looks, but adult zones may have separate rules. Dress for several floors and a riverside journey home.","staff_inclusivity":"Recurring partnerships with Le Girofard and major LGBTQ+ organisers provide stronger evidence than a generic welcoming label. Published transport information is useful, but detailed accessibility for each temporary layout should be checked with the organiser.","review_signal":"Official hours and programming are current and reliable. Review consensus should be read event by event because food service, a concert and a thirteen-hour queer party are fundamentally different products. The building's value is scale and flexibility, not a single permanent mood.","source_urls":["https://www.bienpublic-bordeaux.com/infos-pratiques/","https://vendredix.fr/event/vendredixxl-22/","https://www.le-girofard.org/"],"research_status":"official_operation_plus_verified_queer_partnerships","updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"JOST Bordeaux and Lieu Chéri","patch":{"queue_wait":"Hotel check-in follows normal reception flow; Lieu Chéri uses a separate event entrance and can have ticket checks. The 300-square-metre room handles a substantial audience, but a sold event still needs advance booking. Never assume a public cabaret is running because the hotel is open.","best_nights":"Stay for Gare Saint-Jean convenience, then choose a named drag, cabaret or queer event at Lieu Chéri. The venue's current page may show no upcoming public dates, in which case another neighbourhood is the better nightlife base.","crowd_mix":"Hotel guests, rail travellers, business groups and tourists dominate the property. A queer cabaret brings performers and LGBTQ+ audiences into the separate event room, but does not turn every breakfast or rooftop hour into a community space.","dress_code":"Relaxed contemporary hotel clothes are enough. Cabaret audiences often dress up, yet no standing code is published. Check age limits and the organiser's rules for a specific production.","staff_inclusivity":"The clearest evidence is repeated queer-facing cabaret programming and two positive community safety reports, not an exclusive identity claim. Contact the hotel ahead for chosen-name, room-sharing or accessibility needs rather than expecting the event brand to answer accommodation questions.","review_signal":"Official sources verify the hotel, address and cabaret capacity; community listings verify past queer use. The public event calendar was quiet when checked. That makes JOST a credible programme-based queer-friendly hotel, not a guaranteed nightly queer destination.","source_urls":["https://www.jost-hotel-bordeaux.com/lieu-cheri/","https://congres.bordeaux-tourisme.com/hotellerie/jost-bordeaux.html","https://vibes.lgbt/en/place/lieu-cheri-60624201"],"research_status":"official_hotel_and_venue_plus_community_safety_signal","updated_at":"2026-08-14T00:00:00Z"}}
]
$bordeaux_place_intel$) r(name text,patch jsonb)
)
update public.places p set venue_intel=coalesce(p.venue_intel,'{}'::jsonb)||r.patch,updated_at=timezone('utc',now()) from researched r
where lower(trim(p.city))='bordeaux' and lower(trim(p.name))=lower(trim(r.name));

with researched as (
 select * from jsonb_to_recordset($bordeaux_event_intel$
[
 {"name":"Mois des Fiertés Bordeaux 2026","patch":{"entry_wait":"There was no single gate; each free, registered or ticketed programme used its own access rules.","best_arrival":"Use the official full programme to connect one cultural event, one community event and the march rather than treating the month as one festival site.","crowd_mix":"Queer residents, associations, families, students, artists, researchers, allies and visitors met in different combinations across the city.","dress_code":"No universal code; library talks, outdoor gatherings, drag and adult nightlife each require different preparation.","host_inclusivity":"Municipal backing, French Sign Language interpretation at central Pride moments and a programme distributed across neighbourhoods widen access beyond club culture.","source_urls":["https://www.bordeaux-metropole.fr/agenda/14994330_mois-des-fiertes-2026-6eme-edition","https://www.le-girofard.org/"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Bordeaux Pride March 2026","patch":{"entry_wait":"Free public march with no ticket queue; Place des Quinconces became denser before speeches and movement.","best_arrival":"Around 12:15-12:30 allowed orientation before 13:00 speeches and the 14:00 departure.","crowd_mix":"Local organisations, activists, families, drag artists, elders, youth, allies and regional and international visitors.","dress_code":"Walking shoes, water, sun or rain protection and expressive Pride looks; river wind can change the useful layer.","host_inclusivity":"The official programme included LSF interpretation and linked the march to thirty years of Bordeaux Pride history.","source_urls":["https://www.bordeaux-metropole.fr/agenda/43347290_the-gay-pride-in-bordeaux","https://www.bordeaux-metropole.fr/agenda/14994330_mois-des-fiertes-2026-6eme-edition"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"AfterPride Bordeaux 2026","patch":{"entry_wait":"Free outdoor finish; crowd flow from the march, not ticketing, created the pressure point.","best_arrival":"Following the procession to the site was simplest; later arrivals needed extra time around Saint-Michel and the quays.","crowd_mix":"Marchers, community groups, friends, performers and a wider public who preferred an open-air celebration to a club.","dress_code":"Keep parade shoes and weather layers; this was a park-and-quayside event rather than a polished afterparty.","host_inclusivity":"Free public access extended Pride beyond paid nightlife, though final site accessibility and security information belonged to the live organiser notice.","source_urls":["https://www.bordeaux-metropole.fr/agenda/14994330_mois-des-fiertes-2026-6eme-edition"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Festival Cinémarges 2026","patch":{"entry_wait":"Cinema screenings, free institutional events and the closing concert each used separate reservations or capacity rules.","best_arrival":"Plan around one film strand and leave transfer time between Utopia, Mériadeck, FRAC, CAPC and the evening venues.","crowd_mix":"Queer film audiences, feminist organisers, students, artists, HIV activists, archivists and international cinema visitors.","dress_code":"Everyday cinema clothing works; evening performance and bar events invite more expression but impose no general code.","host_inclusivity":"The programme centred lesbian, gay, trans and feminist resistance and deliberately crossed community and major public institutions.","source_urls":["https://festival.cinemarges.fr/grille-2026","https://alca-nouvelle-aquitaine.fr/fr/agenda/festival-cinemarges-2026"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"VendrediXXL Bordeaux 2026","patch":{"entry_wait":"A large ticketed takeover with the biggest pressure near opening and the late-night club transition; buy before travelling.","best_arrival":"17:15-17:30 catches cabaret and gives time to learn the building before the downstairs electronic floor becomes dense.","crowd_mix":"Broad LGBTQIA+ clubbers, cabaret fans, pop and hyperpop crowds, kink communities and visitors from across the region.","dress_code":"Expressive clubwear is natural; the adult Bestial Zone may have specific consent, age or clothing rules that supersede the general event.","host_inclusivity":"Multiple music and performance zones let different queer nightlife cultures coexist, but explicit adult areas require active boundaries and organiser-led safety.","source_urls":["https://vendredix.fr/event/vendredixxl-22/","https://www.bienpublic-bordeaux.com/infos-pratiques/"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Journées du matrimoine et du queer heritage 2026","patch":{"entry_wait":"Free and without reservation according to the national heritage listing; the opening can still make the small venue busy.","best_arrival":"Visit earlier for the exhibition or arrive before the announced opening talk to hear the community archive context.","crowd_mix":"Feminist organisers, queer archivists, local history audiences, activists, neighbours and heritage-weekend visitors.","dress_code":"Casual daytime clothing; no code.","host_inclusivity":"QueerCode, Le Girofard, GiroArchives and La Boîte sous le lit place queer memory inside a women's-house history rather than as an add-on.","source_urls":["https://journeesdupatrimoine.culture.gouv.fr/w/377623/evenement/19042153/journees-du-matrimoine-patrimoine-et-du-queer-heritage-a-la-maison-des-femmes-de-bordeaux"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Bal Queer #8","patch":{"entry_wait":"Ticket sales open on 28 September; secure entry before the 28 November date rather than relying on the civic-hall scale.","best_arrival":"Arrive near the 19:00 opening to see the room build and catch early performance or participation instructions.","crowd_mix":"Queer dancers, performers, drag communities, artists, friends and people drawn by La Bordelle's militant cultural approach.","dress_code":"Self-invention is part of the pleasure: glamour, drag, practical dance clothes and experimental looks all belong. No compulsory aesthetic is published.","host_inclusivity":"La Bordelle's queer cultural organising and the public Salle des Fêtes partnership create a collective-led alternative to commercial clubbing.","source_urls":["https://www.helloasso.com/associations/la-salle-des-fetes-bordeaux-grand-parc/evenements/bal-queer-8","https://www.bordeaux-tourisme.com/sortir/bars/queer-lgbt"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Drag Me to Rock 2026","patch":{"entry_wait":"Free entry meant no advance ticket, but the 20:00 opening could still fill the hangar around featured sets.","best_arrival":"Before 20:00 for the opening performance and an easier position; stay through the shift from rock to electronic energy.","crowd_mix":"Drag audiences, queer and feminist music communities, rock fans, artists and Pride Month visitors.","dress_code":"Band shirts, drag, denim and colourful night-out looks all fit; practical footwear matters in a converted quay venue.","host_inclusivity":"Médusyne and La Bordelle brought minority representation and queer cultural practice into the collaboration rather than attaching a rainbow label to a standard rock bill.","source_urls":["https://www.bordeaux-metropole.fr/agenda/14994330_mois-des-fiertes-2026-6eme-edition","https://www.medusyne.com/"],"updated_at":"2026-08-14T00:00:00Z"}}
]
$bordeaux_event_intel$) r(name text,patch jsonb)
)
update public.events e set event_intel=coalesce(e.event_intel,'{}'::jsonb)||r.patch,updated_at=timezone('utc',now()) from researched r
where lower(trim(e.city))='bordeaux' and lower(trim(e.name))=lower(trim(r.name));

with researched as (
 select * from jsonb_to_recordset($bordeaux_service_intel$
[
 {"name":"Le Girofard","patch":{"booking_lead_time":"Each permanence has its own route. Contact the centre before travelling for psychological, legal, asylum, violence or health support; social events may be open without an appointment.","best_time":"State the need clearly in the first message so the team can route you to the correct employee, volunteer or member association.","client_mix":"Lesbian, gay, bi, trans, intersex and non-binary people, allies, families, asylum seekers, elders and people affected by violence or isolation.","preparation":"Share only information needed for routing, and ask about confidentiality, language, mobility and whether the address is suitable for the appointment.","provider_inclusivity":"The centre is governed through community associations and supports identity-specific collectives, making its competence structural rather than decorative.","source_urls":["https://www.le-girofard.org/","https://www.gironde.fr/enfance-et-famille/lutte-contre-les-violences/le-girofard"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"CeGIDD Bordeaux","patch":{"booking_lead_time":"Most walk-in windows need no appointment; Tuesday afternoon testing, PrEP and sexology do. Doctolib or phone ahead for those services.","best_time":"Attend early in a walk-in period and disclose exposure timing. For possible HIV exposure within 48 hours, seek urgent PEP care rather than waiting for a routine slot.","client_mix":"Anyone seeking free sexual-health care, including LGBTQ+ people, people using chemsex, people without a regular doctor and those preferring anonymous testing.","preparation":"Bring health information and medication details if available; ask which anatomical sites and infections will be tested and when results return.","provider_inclusivity":"Free anonymous access, dedicated PrEP, sexology and ENIPSE chemsex support directly address needs common in queer communities without restricting service to one identity.","source_urls":["https://www.gironde.fr/lieu/centre-gratuit-dinformation-de-depistage-et-de-diagnostic-cegidd","https://www.sida-info-service.org/annuaire/Centre-De-Depistage-VIH-Sida-Ville-de-Bordeaux"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"ANCRES","patch":{"booking_lead_time":"Use the official calendar for public permanences and email for an individual appointment; workshop capacity can require registration.","best_time":"Choose administrative support for documents, peer sessions for shared experience and a private appointment for a sensitive or complex need.","client_mix":"Trans, non-binary and questioning people, with selected resources for relatives, carers and professionals.","preparation":"Bring only the paperwork relevant to an administrative session. For injection workshops, ask what equipment and medical follow-up the association provides and what remains outside its role.","provider_inclusivity":"ANCRES was created by trans people for trans and non-binary people, grounding its service in peer knowledge and self-determination.","source_urls":["https://ancresassociation.org/","https://www.helloasso.com/associations/ancres"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Maison des Femmes de Bordeaux","patch":{"booking_lead_time":"The social welcome accepts walk-ins during published hours, while a complex issue may benefit from a phone call first.","best_time":"Arrive early in the 14:00-18:00 window and name the practical need—rights, health, work, isolation or administration—so orientation can begin quickly.","client_mix":"All women seeking support, including lesbian, bi, trans and migrant women, as well as participants in feminist cultural and memory work.","preparation":"Bring relevant letters or documents if asking for administrative help, but anonymous listening does not require telling an entire personal history.","provider_inclusivity":"The service combines feminist confidentiality with documented queer partnerships. Its audience remains women, so other LGBTQ+ people should use Le Girofard.","source_urls":["https://maisondesfemmes.net/nos-accueils/accueil-ecoute-orientation/","https://journeesdupatrimoine.culture.gouv.fr/w/377623/evenement/19042153/journees-du-matrimoine-patrimoine-et-du-queer-heritage-a-la-maison-des-femmes-de-bordeaux"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Bordeaux Ville Sans Sida Prevention Kits","patch":{"booking_lead_time":"Order through the official form; delivery or collection timing is confirmed later by email rather than guaranteed instantly.","best_time":"Order before supplies are urgently needed. A recent possible exposure requires medical PEP advice, not a home self-test.","client_mix":"Bordeaux residents across orientations and genders who want discreet HIV self-testing and prevention supplies.","preparation":"Use a private email address, choose delivery or collection and read the test window and instructions before relying on a result.","provider_inclusivity":"The form explicitly recognises varied orientations and genders, offers no-cost discreet access and links self-testing to a wider local prevention network.","source_urls":["https://bordeaux-ville-sans-sida.fr/test-prevention/","https://bordeaux-ville-sans-sida.fr/or/"],"updated_at":"2026-08-14T00:00:00Z"}}
]
$bordeaux_service_intel$) r(name text,patch jsonb)
)
update public.services s set service_intel=coalesce(s.service_intel,'{}'::jsonb)||r.patch,updated_at=timezone('utc',now()) from researched r
where lower(trim(s.city))='bordeaux' and lower(trim(s.name))=lower(trim(r.name));

commit;

select 'places_with_complete_intel' check_name,count(*) result from public.places where lower(trim(city))='bordeaux' and coalesce(venue_intel->>'queue_wait','')<>'' and coalesce(venue_intel->>'best_nights','')<>'' and coalesce(venue_intel->>'crowd_mix','')<>'' and coalesce(venue_intel->>'dress_code','')<>'' and coalesce(venue_intel->>'staff_inclusivity','')<>''
union all select 'events_with_complete_intel',count(*) from public.events where lower(trim(city))='bordeaux' and coalesce(event_intel->>'entry_wait','')<>'' and coalesce(event_intel->>'host_inclusivity','')<>''
union all select 'services_with_complete_intel',count(*) from public.services where lower(trim(city))='bordeaux' and coalesce(service_intel->>'booking_lead_time','')<>'' and coalesce(service_intel->>'provider_inclusivity','')<>''
order by check_name;
